/**
 * FedX evaluates OPTIONAL through its own left-join code (FederationEvaluationStrategy.prepareLeftJoin), which keeps
 * the correlated, scheduled left join for an OPTIONAL with a condition over a sub-select. A sub-select is a bottom-up
 * scope boundary in every position, so the federated result must equal the result of the same query on a single store
 * holding the union of the members' data. The data is split so that FedX evaluates the joins locally.
 */
class FedXSubSelectScopeTest extends SPARQLBaseTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final String PREFIX = "PREFIX : <urn:ex:>\n";

	private final List<Statement> firstMember = List.of(
			st("a", "p", VF.createLiteral(2)),
			st("b", "p", VF.createLiteral(3)),
			st("c", "q", exIri("w")),
			st("d", "q", exIri("w")),
			st("e", "q", exIri("w")));
	private final List<Statement> secondMember = List.of(
			st("c", "r", VF.createLiteral(1)),
			st("d", "r", VF.createLiteral(2)),
			st("e", "r", VF.createLiteral(3)),
			st("d", "z", exIri("y1")));

	private Repository reference;

	@BeforeEach
	void setUpData() throws Exception {
		prepareTest(List.of("/tests/basic/data_emptyStore.ttl", "/tests/basic/data_emptyStore.ttl"));
		try (RepositoryConnection connection = getRepository(1).getConnection()) {
			connection.add(firstMember);
		}
		try (RepositoryConnection connection = getRepository(2).getConnection()) {
			connection.add(secondMember);
		}
		reference = new SailRepository(new MemoryStore());
		try (RepositoryConnection connection = reference.getConnection()) {
			connection.add(firstMember);
			connection.add(secondMember);
		}
	}

	@AfterEach
	void tearDownReference() {
		if (reference != null) {
			reference.shutDown();
		}
	}

	@ParameterizedTest(name = "condition={0}")
	@ValueSource(strings = { "", "FILTER(BOUND(?t))", "FILTER(?t != ?s)" })
	void optionalOverLimitedSubSelectIsEvaluatedIndependently(String condition) {
		// inside the sub-select ?x is fresh: bottom-up it is exactly {t=:c}, which joins with every left row
		String query = PREFIX + """
				SELECT ?s ?x ?t WHERE {
				  ?s :p ?x
				  OPTIONAL { { SELECT ?t WHERE { ?t :r ?x } ORDER BY ?t LIMIT 1 } %s }
				}
				""".formatted(condition);

		assertThat(federated(query, Map.of())).isEqualTo(referenceRows(query, Map.of()))
				.containsExactly("{s=urn:ex:a, t=urn:ex:c, x=2}", "{s=urn:ex:b, t=urn:ex:c, x=3}");
	}

	@ParameterizedTest(name = "condition={0}")
	@ValueSource(strings = { "", "FILTER(?n > 0)" })
	void optionalOverAggregateSubSelectIsEvaluatedIndependently(String condition) {
		String query = PREFIX + """
				SELECT ?s ?n WHERE {
				  ?s :p ?x
				  OPTIONAL { { SELECT (COUNT(?t) AS ?n) WHERE { ?t :r ?x } } %s }
				}
				""".formatted(condition);

		assertThat(federated(query, Map.of())).isEqualTo(referenceRows(query, Map.of()))
				.containsExactly("{n=3, s=urn:ex:a}", "{n=3, s=urn:ex:b}");
	}

	@Test
	void externalBindingReachesATopLevelNestedSubSelect() {
		// RDF4J treats a query's external bindings as constants in the whole query: ?x = 1 selects ?t :r 1 before
		// the LIMIT, exactly as a single store evaluates it
		String query = PREFIX + """
				SELECT ?t WHERE {
				  { SELECT ?t WHERE { ?t :r ?x . ?t :q ?w } ORDER BY DESC(?t) LIMIT 1 }
				}
				""";
		Map<String, Value> bindings = Map.of("x", VF.createLiteral(1));

		assertThat(federated(query, bindings)).isEqualTo(referenceRows(query, bindings))
				.containsExactly("{t=urn:ex:c}");
	}

	private List<String> federated(String query, Map<String, Value> bindings) {
		return rows(fedxRule.getRepository(), query, bindings);
	}

	private List<String> referenceRows(String query, Map<String, Value> bindings) {
		return rows(reference, query, bindings);
	}

	private static List<String> rows(Repository repository, String query, Map<String, Value> bindings) {
		List<String> rows = new ArrayList<>();
		try (RepositoryConnection connection = repository.getConnection()) {
			TupleQuery tupleQuery = connection.prepareTupleQuery(query);
			bindings.forEach(tupleQuery::setBinding);
			try (TupleQueryResult result = tupleQuery.evaluate()) {
				for (BindingSet row : result) {
					TreeMap<String, String> sorted = new TreeMap<>();
					for (String name : row.getBindingNames()) {
						Value value = row.getValue(name);
						if (value != null) {
							sorted.put(name, value.stringValue());
						}
					}
					rows.add(sorted.toString());
				}
			}
		}
		rows.sort(null);
		return rows;
	}

	private static IRI exIri(String local) {
		return VF.createIRI("urn:ex:" + local);
	}

	private static Statement st(String subject, String predicate, Value object) {
		return VF.createStatement(exIri(subject), exIri(predicate), object);
	}
}
